const std = @import("std");
pub fn build(b: *std.Build) void {
    const agent = b.option([]const u8, "agent-source", "Frozen Agent") orelse @panic("agent-source");
    const boundary = b.option([]const u8, "boundary-source", "Authenticated Boundary") orelse @panic("boundary-source");
    const world = b.option([]const u8, "world-source", "Authenticated World") orelse @panic("world-source");
    const legacy = b.option(bool, "legacy", "Predecessor module names") orelse false;
    const data_name = if (legacy) "boundary_data_v2" else "boundary_data";
    const data = b.createModule(.{ .root_source_file = .{ .cwd_relative = b.pathJoin(&.{ boundary, "src/v2/data/root.zig" }) }, .target = b.graph.host, .optimize = .ReleaseSafe });
    const author = b.createModule(.{ .root_source_file = .{ .cwd_relative = b.pathJoin(&.{ boundary, "src/v2/root.zig" }) }, .target = b.graph.host, .optimize = .ReleaseSafe, .imports = &.{.{ .name = data_name, .module = data }} });
    const runtime = b.createModule(.{ .root_source_file = .{ .cwd_relative = b.pathJoin(&.{ world, "src/root.zig" }) }, .target = b.graph.host, .optimize = .ReleaseSafe, .imports = &.{.{ .name = data_name, .module = data }} });
    const native = b.createModule(.{ .root_source_file = .{ .cwd_relative = b.pathJoin(&.{ agent, "test/agent4/native.zig" }) }, .target = b.graph.host, .optimize = .ReleaseSafe, .imports = &.{ .{ .name = data_name, .module = data }, .{ .name = "world", .module = runtime } } });
    b.installArtifact(b.addExecutable(.{ .name = "native", .root_module = native }));
    const deliberation = b.createModule(.{ .root_source_file = .{ .cwd_relative = b.pathJoin(&.{ agent, "src/deliberation.zig" }) }, .target = b.graph.host, .optimize = .ReleaseSafe, .imports = &.{.{ .name = "boundary", .module = author }} });
    const inspector = b.createModule(.{ .root_source_file = .{ .cwd_relative = b.pathJoin(&.{ agent, "test/agent4/multi_probe.zig" }) }, .target = b.graph.host, .optimize = .ReleaseSafe, .imports = &.{ .{ .name = "boundary", .module = author }, .{ .name = "deliberation", .module = deliberation } } });
    b.installArtifact(b.addExecutable(.{ .name = "inspector", .root_module = inspector }));
}

