const std = @import("std");
const d = @import("data");
const r = d.relocation;
pub fn main(init: std.process.Init) !void {
    var args = init.minimal.args.iterate();
    _ = args.next();
    const path = args.next() orelse return error.MissingImage;
    const bytes = try std.Io.Dir.cwd().readFileAlloc(init.io, path, init.gpa, .limited(64 << 20));
    defer init.gpa.free(bytes);
    var decoded = try d.program_image.decode(init.gpa, bytes);
    defer decoded.deinit();
    const program = decoded.program;
    var arena = std.heap.ArenaAllocator.init(init.gpa);
    defer arena.deinit();
    const a = arena.allocator();
    const sizes = try r.sizes(program);
    var maps: r.Maps = undefined;
    var seen: [r.kind_count][]bool = undefined;
    for (sizes, &maps, &seen) |count, *map, *visited| {
        const ids = try a.alloc(u64, count);
        for (ids, 0..) |*id, index| id.* = index;
        map.* = ids;
        visited.* = try a.alloc(bool, count);
        @memset(visited.*, false);
    }
    var waiting: std.ArrayList(r.Reference) = .empty;
    try waiting.appendSlice(a, &.{ .{ .kind = .function, .id = program.roots.entry },
        .{ .kind = .schema, .id = program.roots.result }, .{ .kind = .schema, .id = program.roots.failure } });
    while (waiting.pop()) |ref| {
        const kind = @intFromEnum(ref.kind);
        if (seen[kind][@intCast(ref.id)]) continue;
        seen[kind][@intCast(ref.id)] = true;
        var scratch = std.heap.ArenaAllocator.init(init.gpa);
        defer scratch.deinit();
        var found: std.ArrayList(r.Reference) = .empty;
        const m: r.Mapper = .{ .allocator = scratch.allocator(), .maps = maps, .observed = &found };
        const id: usize = @intCast(ref.id);
        switch (ref.kind) {
            .schema => _ = try m.schema(program.schemas[id]),
            .constant => _ = try m.literal(program.constants[id]),
            .effect => _ = try m.effect(program.effects[id]),
            .function => _ = try m.function(program.functions[id]),
            .block => _ = try m.block(program.blocks[id]),
            .handler => _ = try m.handler(program.handlers[id]),
            .capture => _ = try m.capture(program.scopes.captures[id]),
            .region => {},
            .resource => _ = try m.resource(program.scopes.resources[id]),
            .constructor => _ = try m.constructor(program.constructors[id]),
        }
        try waiting.appendSlice(a, found.items);
    }
    var buffer: [4096]u8 = undefined;
    var out = std.Io.File.stdout().writer(init.io, &buffer);
    try out.interface.writeAll("{\"catalogs\":[");
    inline for (std.meta.fields(r.Kind), 0..) |field, index| {
        var reached: usize = 0;
        for (seen[index]) |visited| reached += @intFromBool(visited);
        if (index != 0) try out.interface.writeByte(',');
        try std.json.Stringify.value(.{ .kind = field.name, .total = sizes[index], .reachable = reached }, .{}, &out.interface);
    }
    try out.interface.writeAll("]}\n");
    try out.interface.flush();
}

